(6265536, 926845, 114225, '<td valign="top">A very nice scene. It''s interesting that you chose more of a square crop for this. Feels like you included the boring sky instead of the interesting landscape.</td>', 'A very nice scene. It''s interesting that you chose more of a square crop for this. Feels like you included the boring sky instead of the interesting landscape.', '2010-12-31 23:50:35.000000', NULL, 1),
(6265537, 926796, 114225, '<td valign="top">Yum! I like how much details this shows at the edges, although I feel the depth of field is show shallow that I think it''s taking away from more of the yummy details that could have been shown.</td>', 'Yum! I like how much details this shows at the edges, although I feel the depth of field is show shallow that I think it''s taking away from more of the yummy details that could have been shown.', '2010-12-31 23:52:35.000000', NULL, 1),
