(6265539, 926965, 114225, '<td valign="top">Great job setting up this shot. The choice of plate is perfect, and the depth of field is very nice. However, is it just me, or is there VERY pixelated?</td>', 'Great job setting up this shot. The choice of plate is perfect, and the depth of field is very nice. However, is it just me, or is there VERY pixelated?', '2010-12-31 23:54:41.000000', NULL, 1),
(6265540, 927005, 114225, '<td valign="top">Great idea for the challenge. Good choice on the container and back lighting as well. However, I think it would have been even nicer if the back lighting was brighter such that it turned to wait (seeing the wall details isn''t appealing here).</td>', 'Great idea for the challenge. Good choice on the container and back lighting as well. However, I think it would have been even nicer if the back lighting was brighter such that it turned to wait (seeing the wall details isn''t appealing here).', '2010-12-31 23:58:12.000000', NULL, 1),
(6265542, 926503, 114225, '<td valign="top">Well done. Portrait orientation for a landscape photo can be a dangerous choice, but it really works wonders here.</td>', 'Well done. Portrait orientation for a landscape photo can be a dangerous choice, but it really works wonders here.', '2010-12-31 23:59:46.000000', NULL, 1),
(6265544, 926269, 114225, '<td valign="top">Cool perspective for the city. I find myself wanting a bit more contrast to this photo. Seems like it''s really lacking some deep balcks.</td>', 'Cool perspective for the city. I find myself wanting a bit more contrast to this photo. Seems like it''s really lacking some deep balcks.', '2011-01-01 00:01:35.000000', NULL, 1),
